// Large-collection scores are stored gzip-compressed (practice.json.gz); a server may also have decoded them already.
async function readScore(response,url){if(!/\.gz(\?|$)/.test(url))return response.json();const bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]!==0x1f||bytes[1]!==0x8b)return JSON.parse(new TextDecoder().decode(bytes));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text());}
