// The microphone hears a note a little after it is played (the analysis window); timing allows for that.
// The microphone reports when each note was struck (`ago`), so only the sound card's own delay remains.
const inputLatency=()=>mode==='microphone'?.02:0;
// With the microphone a grace note may be passed over when the note it leads to is heard (it can be missed
// when played a few milliseconds before the main note).
function newMatcher(){return new E.Matcher(events,{graceOptional:mode==='microphone'});}
// Wait mode: the line moves at the tempo, like Listen, and stops at each note until it is played right.
// A note played before the line reaches it counts (the line glides up to it); how early or late each
// group starts is kept for the timing score.
// Move the line and note the moment it reaches the next note (exactly, between animation frames).
